#include <iostream>
#include <vector>
#include <tuple>
#include <algorithm>

int main() {
    using namespace std;
    unsigned N, Q;
    cin >> N >> Q;
    vector<tuple<unsigned, unsigned, unsigned>> event;
    for (unsigned i{}; i < Q; ++i) {
        unsigned L, R, X;
        cin >> L >> R >> X;
        --L;
        --X;
        event.emplace_back(L, X, 1); // X を追加するイベント
        event.emplace_back(R, X, -1); // X を削除するイベント
    }
    event.emplace_back(N, 0, 0); // 番兵

    ranges::sort(event);
    vector<unsigned> counter(Q); // counter[i] := i を追加しているイベントがいくつあるか
    unsigned ans{}, now{};
    for (const auto &[t, x, v] : event) {
        while (t != now) {
            ++now;
            cout << ans << " ";
        }
        if (counter[x] == 0) ++ans; // 0 から増えたら答えを増やす
        counter[x] += v;
        if (counter[x] == 0) --ans; // 0 に減ったら答えを減らす
    }
    cout << endl;
    return 0;
}
